// Repro Code: renders an OverflowMenu on a grey background so you can see
// that the default menu panel uses the same grey shade and has poor contrast.
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { OverflowMenu, OverflowMenuItem } from 'carbon-components-react';
import OverflowMenuVertical16 from '@carbon/icons-react/lib/overflow-menu--vertical/16';

function App() {
  return (
    <div
      style={{
        backgroundColor: '#f4f4f4',
        height: '100vh',
        padding: '2rem',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'flex-start',
      }}
    >
      <OverflowMenu
        renderIcon={OverflowMenuVertical16}
        ariaLabel="Overflow menu"
        menuOptionsClass="my-custom-menu"
      >
        <OverflowMenuItem itemText="Option 1" />
        <OverflowMenuItem itemText="Option 2" />
        <OverflowMenuItem itemText="Option 3" />
        <OverflowMenuItem itemText="Option 4" />
      </OverflowMenu>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
